// Ideal mechanical feedback fixture. Limits follow STEP/DIR, not command names.
#include "wokwi-api.h"
#include <stdlib.h>
typedef struct{pin_t step,dir,request,enable,up,down,occupied;uint32_t jam,service;int position,lastService;buffer_t frame;uint8_t pixels[240*200*4];}Plant;
static void rect(Plant*p,int x,int y,int w,int h,int r,int g,int b){for(int yy=y;yy<y+h&&yy<200;yy++)for(int xx=x;xx<x+w&&xx<240;xx++){if(xx<0||yy<0)continue;int n=(yy*240+xx)*4;p->pixels[n]=r;p->pixels[n+1]=g;p->pixels[n+2]=b;p->pixels[n+3]=255;}}
static void feedback(Plant*p){pin_write(p->up,p->position==0?LOW:HIGH);pin_write(p->down,p->position==100?LOW:HIGH);}
static void draw(Plant*p){rect(p,0,0,240,200,232,240,235);rect(p,8,8,224,184,255,255,255);rect(p,20,20,4,155,170,189,179);rect(p,216,20,4,155,170,189,179);rect(p,20,20,200,4,170,189,179);if(pin_read(p->occupied)){rect(p,83,30,74,85,53,102,138);rect(p,91,36,58,17,174,211,226);rect(p,91,88,58,16,174,211,226);rect(p,77,42,6,17,35,48,52);rect(p,157,42,6,17,35,48,52);rect(p,77,81,6,17,35,48,52);rect(p,157,81,6,17,35,48,52);}rect(p,82,166,76,13,73,92,83);int h=8+(100-p->position)*64/100;rect(p,103,166-h,34,h,199,65,64);for(int y=166-h+9;y<160;y+=22)rect(p,103,y,34,7,247,231,182);rect(p,24,184,p->position*192/100,5,48,156,115);if(attr_read(p->jam))rect(p,205,30,12,12,225,144,40);buffer_write(p->frame,0,p->pixels,sizeof(p->pixels));}
static void changed(void*data,pin_t pin,uint32_t value){Plant*p=data;if(pin==p->step&&value==HIGH&&pin_read(p->request)==LOW&&!attr_read(p->jam)){p->position+=pin_read(p->dir)?1:-1;if(p->position<0)p->position=0;if(p->position>100)p->position=100;feedback(p);}}
static void tick(void*data){Plant*p=data;pin_write(p->enable,pin_read(p->request)==HIGH||attr_read(p->jam)?HIGH:LOW);int service=attr_read(p->service);if(service!=p->lastService&&pin_read(p->request)==HIGH){p->lastService=service;p->position=service;feedback(p);}draw(p);}
void chip_init(){Plant*p=calloc(1,sizeof(Plant));p->step=pin_init("STEP",INPUT_PULLDOWN);p->dir=pin_init("DIR",INPUT_PULLDOWN);p->request=pin_init("REQUEST_ENABLE",INPUT_PULLUP);p->enable=pin_init("DRIVER_ENABLE",OUTPUT_HIGH);p->up=pin_init("UP",OUTPUT_LOW);p->down=pin_init("DOWN",OUTPUT_HIGH);p->occupied=pin_init("OCCUPIED",INPUT_PULLDOWN);pin_init("GND",INPUT);p->jam=attr_init("jam",0);p->service=attr_init("servicePosition",0);p->position=p->lastService=attr_read(p->service);uint32_t width,height;p->frame=framebuffer_init(&width,&height);const pin_watch_config_t config={.edge=BOTH,.pin_change=changed,.user_data=p};pin_watch(p->step,&config);feedback(p);draw(p);const timer_config_t timer={.callback=tick,.user_data=p};timer_start(timer_init(&timer),50000,true);}
